        if(!s.adv.badges?.includes('Forêt'))return '神奥森林徽章后开放地下探险';
        if(['exit','team','restore','travel','travelFirst'].includes(e.preparation?.phase))return '先完成补练队伍与原任务的切换';
        const status=undergroundStatus(s,now);
