            if((s.adv.tower||s.adv.league||s.adv.zone)&&s.adv.speed!==this.e.settings.speed){if(this.page('adventure'))this.e.driver.click($(`#speed-btns [data-speed="${this.e.settings.speed}"]`),'设置活动战斗速度');return;}
